"use client";
import { FormEvent, ReactNode, useEffect, useMemo, useRef, useState } from "react";
import { BrandLoader, DialogSaveFeedback, FormBoundary, useModalFocus, useWorkspace } from "./workspace-state";
import { AgreementPreview, ClientEditor, RecordForm } from "./record-forms";
import { MonthCarryForward, ProjectBoard } from "./project-board";
import { clientLabels } from "../lib/client-labels";
import { ActivityLog } from "./activity-log";

type Row = Record<string, string | number | boolean | null | undefined>;
type Data = { member?: Row; clients: Row[]; revenue: Row[]; pipeline: Row[]; calls: Row[]; meetings: Row[]; invoices: Row[]; payments: Row[]; agreements: Row[]; documents: Row[]; vendors: Row[]; members: Row[]; teamSummary: Row[]; pipelineSettings?: Row };
type Scope = "overall" | "team";
const blank: Data = { clients: [], revenue: [], pipeline: [], calls: [], meetings: [], invoices: [], payments: [], agreements: [], documents: [], vendors: [], members: [], teamSummary: [], pipelineSettings: { probabilities: '{"l1":20,"l2":50,"l3":100,"l4":100,"l5":100}' } };
const nav = ["Dashboard", "Clients", "Revenue", "Pipeline", "Calls", "Calendar", "Invoices", "Vendors", "Agreements", "Team", "Activity log"];
const stages = ["l1", "l2", "l3", "l4", "l5"];
const stageLabels: Record<string, string> = { l1: "L1 - Quotation Submitted", l2: "L2 - In Negotiation", l3: "L3 - Confirmed, Not Executed", l4: "L4 - Executed, Not Billed", l5: "L5 - Billed" };
const reports: Record<string, { target: number; mtd: number }> = { "Pratik Darji": { target: 1500000, mtd: 300000 }, "Yogesh Pawar": { target: 700000, mtd: 100000 }, "Mukesh Mishra": { target: 1500000, mtd: 250000 }, "Omkar Sawant": { target: 1300000, mtd: 200000 } };
const m = new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 });
const s = (r: Row | undefined | null, k: string) => String(r?.[k] ?? "");
const n = (r: Row | undefined, k: string) => Number(r?.[k] || 0) / 100;
const projected = (r: Row | undefined) => r?.projectedRevenueMinor !== undefined && r?.projectedRevenueMinor !== null ? n(r, "projectedRevenueMinor") : n(r, "revenueMinor");
const projectedMargin = (r: Row | undefined) => r?.projectedMarginMinor !== undefined && r?.projectedMarginMinor !== null ? n(r, "projectedMarginMinor") : n(r, "marginMinor");
const actual = (r: Row | undefined) => r?.actualRevenueMinor === null || r?.actualRevenueMinor === undefined || r?.actualRevenueMinor === "" ? null : n(r, "actualRevenueMinor");
const actualMargin = (r: Row | undefined) => r?.actualMarginMinor === null || r?.actualMarginMinor === undefined || r?.actualMarginMinor === "" ? null : n(r, "actualMarginMinor");
const revenueMonth = (r: Row | undefined) => s(r, "revenueMonth") || s(r, "entryDate").slice(0, 7);
const monthLabel = (month: string) => { if (!/^\d{4}-\d{2}$/.test(month)) return month || "—"; const [year, number] = month.split("-").map(Number); return new Date(year, number - 1, 1).toLocaleDateString("en-IN", { month: "long", year: "numeric" }); };
const revenueStatus = (r: Row | undefined) => { const a = actual(r); const p = projected(r); return a === null || a === 0 ? "Projected" : a < p ? "Partly received" : "Received"; };
const today = () => new Date().toISOString().slice(0, 10);
const fmtDate = (v: string) => { if (!v) return "—"; const d = new Date(v.length === 10 ? v + "T00:00:00" : v); return Number.isNaN(d.getTime()) ? v : d.toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" }); };
const addDays = (v: string, days: number) => { const d = new Date(v + "T00:00:00"); d.setDate(d.getDate() + days); return d.toISOString().slice(0, 10); };
const displayName = (r: Row | undefined) => s(r, "fullName");
const displayEmail = (r: Row | undefined) => { const email = s(r, "email"); return email.includes("@secondmedic.com") || email.includes("@imported.local") || email.includes("@team.local") ? "Email not provided" : email || "Email not provided"; };
const icons: Record<string, string> = { Dashboard: "⌂", Clients: "◌", Revenue: "₹", Pipeline: "↗", Calls: "⌁", Calendar: "□", Invoices: "▤", Vendors: "◈", Agreements: "◫", Team: "♧" };
function actionLabel(view: string) { if (view === "Revenue") return "Add revenue"; if (view === "Pipeline") return "Add opportunity"; if (view === "Calls") return "Log call"; if (view === "Calendar") return "Fix meeting"; if (view === "Invoices") return "Add invoice"; if (view === "Vendors") return "Add vendor"; if (view === "Agreements") return "Add agreement"; return "Add client"; }
function modalTitle(view: string) { if (view === "Revenue") return "Record revenue and margin"; if (view === "Pipeline") return "Add pipeline opportunity"; if (view === "Calls") return "Log cold call"; if (view === "Calendar") return "Fix client meeting"; if (view === "Invoices") return "Add invoice"; if (view === "Vendors") return "Add vendor payable"; if (view === "Agreements") return "Add agreement"; return "Add a client"; }

export default function Home() {
  const workspace = useWorkspace<Data>(blank);
  const { data, loading, notice, setNotice, saving, save, load } = workspace;
  const [view, setView] = useState("Dashboard");
  const [menuOpen, setMenuOpen] = useState(false);
  const [scope, setScope] = useState<Scope>("overall");
  const [selectedMember, setSelectedMember] = useState("");
  const [recordOpen, setRecordOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Row | null>(null);
  const [agreementOpen, setAgreementOpen] = useState<Row | null>(null);
  const [callsOpen, setCallsOpen] = useState(false);
  const [callPreview, setCallPreview] = useState<{ row: Record<string, string>; error: string }[]>([]);
  const [teamOpen, setTeamOpen] = useState<string | null>(null);
  const [authOpen, setAuthOpen] = useState(false);
  const [calendarSeed, setCalendarSeed] = useState("");
  const [revenueActualOpen, setRevenueActualOpen] = useState<Row | null>(null);
  const [paymentOpen, setPaymentOpen] = useState<Row | null>(null);
  const [pipelineInvoiceOpen, setPipelineInvoiceOpen] = useState<Row | null>(null);
  const [pipelineSettingsOpen, setPipelineSettingsOpen] = useState(false);
  const [filters, setFilters] = useState<Record<string, string>>({ clientSearch: "", clientStaff: "all", clientStatus: "all", revenueStaff: "all", revenueRange: "this", revenueFrom: "", revenueTo: "", dashboardMonth: new Date().toISOString().slice(0, 7), pipelineStaff: "all", pipelineTeam: "all", invoiceFilter: "all", vendorSearch: "", vendorStaff: "all" });
  const [calendarMode, setCalendarMode] = useState<"month" | "week" | "day">("month");
  const [calendarDate, setCalendarDate] = useState(new Date());
  const anyModal = recordOpen || !!editingClient || !!agreementOpen || callsOpen || !!teamOpen || authOpen || !!revenueActualOpen || !!paymentOpen || !!pipelineInvoiceOpen || pipelineSettingsOpen;
  const closeForms = () => { if (saving) return; setRecordOpen(false); setEditingClient(null); setAgreementOpen(null); setCallsOpen(false); setTeamOpen(null); setAuthOpen(false); setRevenueActualOpen(null); setPaymentOpen(null); setPipelineInvoiceOpen(null); setPipelineSettingsOpen(false); };
  useModalFocus(anyModal, closeForms);
  useEffect(() => { workspace.setModalOpen(anyModal); }, [anyModal]);
  useEffect(() => { window.scrollTo({ top: 0, left: 0 }); setMenuOpen(false); }, [view]);
  const clients = useMemo(() => Object.fromEntries(data.clients.map((row) => [s(row, "id"), row])), [data.clients]);
  const labels = useMemo(() => clientLabels(data.clients), [data.clients]);
  const client = (id: string) => labels[id] || "Unlinked prospect";
  const member = (id: string) => data.members.find((row) => s(row, "id") === id);
  const owner = (id: string) => displayName(member(id)) || "Unassigned";
  const paid = (id: string) => data.payments.filter((row) => s(row, "invoiceId") === id).reduce((sum, row) => sum + n(row, "amountMinor"), 0);
  const setFilter = (key: string, value: string) => setFilters((old) => ({ ...old, [key]: value }));
  async function submit(event: FormEvent<HTMLFormElement>, action: string) {
    event.preventDefault();
    const form = event.currentTarget, fd = new FormData(form), file = fd.get("file");
    const body = Object.fromEntries(fd.entries()) as Record<string, unknown>;
    delete body.file; body.action = action;
    if (action === "invoice" && !body.dueDate && body.issueDate && body.clientId) body.dueDate = addDays(String(body.issueDate), Number(s(clients[String(body.clientId)], "paymentTermsDays")) || 30);
    const isCsv = file instanceof File && file.size > 0 && (/\.csv$/i.test(file.name) || file.type === "text/csv");
    if (isCsv && ["client", "invoice"].includes(action)) { body.action = action === "client" ? "bulk_clients" : "bulk_invoices"; body.csv = await file.text(); }
    const attachment = file instanceof File && file.size && !isCsv && ["invoice", "agreement"].includes(action) ? { file, clientId: String(body.clientId || ""), entityType: action } : undefined;
    await save(body, attachment ? "Saved. File uploaded successfully." : "Saved successfully.", attachment, () => { form.reset(); setRecordOpen(false); });
  }
  async function saveClientEdit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()) as Record<string, unknown>; body.action = "client_update"; body.clientId = s(editingClient, "id"); await save(body, "Client updated. Linked records remain connected.", undefined, () => setEditingClient(null)); }
  async function saveRevenueActual(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()) as Record<string, unknown>; body.action = "revenue_actual_update"; body.revenueId = s(revenueActualOpen, "id"); await save(body, "Actual revenue updated.", undefined, () => setRevenueActualOpen(null)); }
  async function movePipeline(id: string, stage: string) { if (stage === "l5") { const item = data.pipeline.find((row) => s(row, "id") === id); if (item) setPipelineInvoiceOpen(item); return; } await save({ action: "pipeline_update", pipelineId: id, stage }, "Pipeline stage updated."); }
  async function savePipelineInvoice(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()) as Record<string, unknown>; body.action = "pipeline_update"; body.pipelineId = s(pipelineInvoiceOpen, "id"); body.stage = "l5"; await save(body, "Deal moved to L5 and invoice created.", undefined, () => setPipelineInvoiceOpen(null)); }
  async function savePayment(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()) as Record<string, unknown>; body.action = "payment"; body.invoiceId = s(paymentOpen, "id"); body.clientId = s(paymentOpen, "clientId"); await save(body, "Payment recorded and invoice updated.", undefined, () => setPaymentOpen(null)); }
  async function savePipelineSettings(values: Record<string, string>) { await save({ action: "pipeline_settings", probabilities: values }, "Pipeline probabilities updated.", undefined, () => setPipelineSettingsOpen(false)); }
  async function saveAgreementDetails(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const fd = new FormData(event.currentTarget), file = fd.get("file"); const body = Object.fromEntries(fd.entries()) as Record<string, unknown>; delete body.file; body.action = "agreement_update"; body.agreementId = s(agreementOpen, "id"); const attachment = file instanceof File && file.size ? { file, clientId: s(agreementOpen, "clientId"), entityType: "agreement" } : undefined; await save(body, "Agreement details and file saved.", attachment, () => setAgreementOpen(null)); }
  async function resetPassword(id: string) { await save({ action: "reset_password", memberId: id }, "Temporary password generated."); }
  async function removeMember(id: string) { await save({ action: "team_member_remove", memberId: id }, "Team member removed."); }
  function openMeeting(value: string) { setCalendarSeed(value + "T09:00"); setRecordOpen(true); }
  function parseCalls(file: File) { const reader = new FileReader(); reader.onload = () => { const lines = String(reader.result || "").split(/\r?\n/).map((line) => line.trim()).filter(Boolean); if (lines.length < 2) return setNotice("The file needs a header row and one call."); const headers = lines[0].split(",").map((header) => header.trim().replace(/^"|"$/g, "")); const seen = new Set<string>(); setCallPreview(lines.slice(1).map((line) => { const values = line.split(",").map((value) => value.trim().replace(/^"|"$/g, "")); const row = Object.fromEntries(headers.map((header, i) => [header, values[i] || ""])); const key = (row.clientId || row.client || row.prospectName) + "|" + row.calledAt + "|" + row.outcome; const error = !row.prospectName && !row.clientId && !row.client ? "Client or prospect is required" : !row.calledAt ? "Called at is required" : seen.has(key) ? "Duplicate row" : ""; seen.add(key); return { row, error }; })); }; reader.readAsText(file); }
  async function saveCalls() { const rows = callPreview.filter((entry) => !entry.error).map((entry) => entry.row); if (!rows.length) return setNotice("Fix preview errors before saving."); await save({ action: "bulk_calls", rows }, "Calls imported.", undefined, () => { setCallsOpen(false); setCallPreview([]); }); }
  function downloadTemplate() { const blob = new Blob(["clientId,prospectName,calledAt,outcome,durationSeconds,nextFollowUpAt,notes\n,Example Health,2026-10-15T10:30,connected,120,2026-10-16T11:00,Discussed proposal"], { type: "text/csv" }); const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = "cold-call-template.csv"; a.click(); }
  const options = <><option value="">Choose client</option>{data.clients.slice().sort((a, b) => client(s(a, "id")).localeCompare(client(s(b, "id")))).map((row) => <option key={s(row, "id")} value={s(row, "id")}>{client(s(row, "id"))}</option>)}</>;
  const overdue = data.invoices.filter((row) => s(row, "dueDate") < today() && n(row, "totalMinor") > paid(s(row, "id")));
  const expiring = data.agreements.filter((row) => s(row, "expiryDate") && s(row, "expiryDate") <= addDays(today(), 60));
  const props = { data, client, owner, paid, overdue, expiring, scope, setScope, selectedMember, setSelectedMember, setEditingClient, setRevenueActual: setRevenueActualOpen, movePipeline, openMeeting, calendarMode, setCalendarMode, calendarDate, setCalendarDate, filters, setFilter, teamOpen, setTeamOpen, resetPassword, removeMember, currentMember: data.member, setPaymentOpen, setPipelineSettingsOpen, savePipelineSettings, paymentOpen, pipelineInvoiceOpen, setPipelineInvoiceOpen, savePayment, savePipelineInvoice, agreementOpen, saveAgreementDetails, pipelineSettingsOpen, setAgreementOpen, save };
  return <main className={"crm-shell" + (workspace.changed ? " records-updated" : "")} aria-busy={saving || workspace.refreshing}>
    {(saving || workspace.refreshing) && <div className="workspace-progress" role="progressbar" aria-label={saving ? "Saving changes" : "Refreshing team records"}/>}
    <div className="mobile-topbar"><a href="#top" className="mobile-brand"><HeartbeatIcon/>SecondMedic</a><button type="button" className="mobile-menu-toggle" aria-label="Menu" aria-expanded={menuOpen} aria-controls="workspace-menu" onClick={() => setMenuOpen(!menuOpen)}>☰</button></div>
    {menuOpen && <button className="mobile-drawer-backdrop" aria-label="Close menu" onClick={() => setMenuOpen(false)}/>}
    <aside id="workspace-menu" className={"crm-nav" + (menuOpen ? " mobile-open" : "")}><a className="logo" href="#top"><HeartbeatIcon/><div>SecondMedic</div></a><p className="workspace">SALES WORKSPACE</p><nav aria-label="Main navigation">{nav.map((item) => <button key={item} onClick={() => { closeForms(); setView(item); setMenuOpen(false); }} aria-current={view === item ? "page" : undefined} className={view === item ? "selected" : ""}><i aria-hidden="true">{icons[item]}</i>{item}</button>)}</nav><div className="profile"><b>{displayName(data.member) || "Workspace member"}</b><small>{s(data.member, "role") || "CRM member"}</small><button className="profile-link" onClick={() => setAuthOpen(true)}>Forgot password?</button></div></aside>
    <section className="crm-main" id="top"><header className="topbar"><div><p className="kicker">{view === "Dashboard" ? "SALES UPDATE" : "CRM WORKSPACE"}</p><h1>{view === "Dashboard" ? "Performance command center" : view}</h1><p>{view === "Dashboard" ? "One view for the business, every team and every individual." : "Manage " + view.toLowerCase() + " with a reliable shared history."}</p><small className="last-updated">{workspace.lastUpdated ? `Last updated ${workspace.lastUpdated} IST` : "Connecting to your workspace"}{workspace.refreshing && " · Updating…"}</small></div><div className="header-actions">{view === "Calls" && <><button className="ghost" disabled={saving} onClick={() => setCallsOpen(true)}>Import calls</button><button className="ghost" disabled={saving} onClick={downloadTemplate}>Sample template</button></>}<button className="ghost" disabled={saving || loading || workspace.refreshing} onClick={() => void load()}>{workspace.refreshing ? <><span className="button-spinner"/>Refreshing…</> : "↻ Refresh"}</button>{!["Dashboard", "Team", "Activity log"].includes(view) && <button className="primary" disabled={saving || loading} onClick={() => { closeForms(); setRecordOpen(true); }}>+ {actionLabel(view)}</button>}</div></header>
      {notice && <div className={"notice" + (saving ? " notice-saving" : "")} role="status" aria-live="polite">{saving ? <span className="button-spinner"/> : <span aria-hidden="true">✓</span>}{notice}<button aria-label="Dismiss message" onClick={() => setNotice("")}>×</button></div>}
      {workspace.saveError && !anyModal && <div className="workspace-error" role="alert"><span>{workspace.saveError}</span><button className="ghost" disabled={saving} onClick={() => void workspace.retrySave()}>Retry save</button></div>}
      <DialogSaveFeedback open={anyModal} error={workspace.saveError} saving={saving} onRetry={() => void workspace.retrySave()}/>
      {workspace.loadError && <div className="workspace-error" role="alert"><span><b>Could not load data</b><br/>{workspace.loadError}</span><button className="ghost" disabled={workspace.refreshing || loading} onClick={() => void load()}>Retry</button></div>}
      {workspace.slow && <div className="workspace-slow" role="status">Taking longer than usual. Your records are being requested safely.</div>}
      {loading ? <BrandLoader/> : !workspace.lastUpdated ? null : <fieldset className="workspace-content" disabled={saving} aria-busy={saving}>
        <div className="page-transition" key={view}><View view={view} {...props}/></div>
        {recordOpen && <div className="record-modal-backdrop" onClick={closeForms}><section className="entry record-modal" role="dialog" aria-modal="true" aria-label={modalTitle(view)} onClick={(e) => e.stopPropagation()}><button className="modal-close" aria-label="Close form" type="button" onClick={closeForms}>×</button><div className="entry-intro"><p className="kicker">WORKSPACE ENTRY</p><h2>{modalTitle(view)}</h2><p>{view === "Agreements" ? "Upload a PDF or image, link its client and review the agreement details." : "Save once. Your team’s records refresh after the update."}</p></div><div className="entry-form"><FormBoundary onClose={closeForms}><RecordForm view={view} options={options} data={data} submit={submit} seed={calendarSeed} onClose={closeForms}/></FormBoundary></div></section></div>}
        {editingClient && <FormBoundary onClose={closeForms}><ClientEditor client={editingClient} data={data} onClose={closeForms} onSave={saveClientEdit}/></FormBoundary>}
        {revenueActualOpen && <RevenueActualDialog revenue={revenueActualOpen} client={client} onClose={closeForms} onSave={saveRevenueActual}/>}
        {callsOpen && <CallImportDialog preview={callPreview} onFile={parseCalls} onClose={closeForms} onSave={saveCalls}/>}
        {teamOpen && <TeamMemberDialog team={teamOpen} onClose={closeForms} onSave={async (body) => { await save({ ...body, action: "team_member_add", teamName: teamOpen }, "Team member added.", undefined, () => setTeamOpen(null)); }}/>}
        {authOpen && <AuthHelpDialog onClose={closeForms}/>}
      </fieldset>}
    </section>
  </main>;
}

function HeartbeatIcon() { return <svg className="heartbeat-icon" viewBox="0 0 40 40" aria-hidden="true"><circle cx="20" cy="20" r="17" fill="none"/><path d="M2 21h8l4-7 5 15 5-23 5 15h9" fill="none"/></svg>; }

function View(p: any) {
  let screen: ReactNode;
  if (p.view === "Activity log") return <ActivityLog data={p.data}/>;
  if (p.view === "Dashboard") screen = <Dashboard {...p}/>; else if (p.view === "Clients") screen = <Clients {...p}/>; else if (p.view === "Revenue") screen = <Revenue {...p}/>; else if (p.view === "Pipeline") screen = <ProjectBoard {...p}/>; else if (p.view === "Calls") screen = <Calls {...p}/>; else if (p.view === "Calendar") screen = <Calendar {...p}/>; else if (p.view === "Invoices") screen = <Invoices {...p}/>; else if (p.view === "Vendors") screen = <Vendors {...p}/>; else if (p.view === "Agreements") screen = <Agreements {...p}/>; else screen = <Team {...p}/>;
  return <>{screen}{p.agreementOpen && <AgreementPreview agreement={p.agreementOpen} client={p.client} onClose={() => p.setAgreementOpen(null)} onSave={p.saveAgreementDetails}/>} {p.paymentOpen && <PaymentDialog invoice={p.paymentOpen} onClose={() => p.setPaymentOpen(null)} onSave={p.savePayment}/>} {p.pipelineInvoiceOpen && <PipelineInvoiceDialog deal={p.pipelineInvoiceOpen} onClose={() => p.setPipelineInvoiceOpen(null)} onSave={p.savePipelineInvoice}/>} {p.pipelineSettingsOpen && <PipelineSettingsDialog settings={p.data.pipelineSettings} onClose={() => p.setPipelineSettingsOpen(false)} onSave={p.savePipelineSettings}/>}</>;
}

function Dashboard(p: any) {
  const [showFocus, setShowFocus] = useState(false); const [showPipeline, setShowPipeline] = useState(false);
  const staff: Row[] = p.data.members.filter((row: Row) => s(row, "role") !== "admin");
  const chosen = staff.find((row: Row) => s(row, "id") === p.selectedMember) || staff[0];
  const teams = [...new Map<string, Row>(staff.map((row: Row): [string, Row] => [s(row, "teamName"), row])).values()];
  const scoped = p.scope === "overall" ? staff : staff.filter((row: Row) => s(row, "teamName") === s(chosen, "teamName"));
  const month = p.filters.dashboardMonth || new Date().toISOString().slice(0, 7); const ids = new Set(scoped.map((row: Row) => s(row, "id")));
  const backup = p.data.pipeline.filter((row: Row) => !row.completedAt && ids.has(s(row, "ownerMemberId")) && ["l1", "l2"].includes(s(row, "stage")));
  const revenue = p.data.revenue.filter((row: Row) => ids.has(s(row, "ownerMemberId")) && revenueMonth(row) === month);
  const confirmed = revenue.map((entry: Row) => ({ ...entry, expectedRevenueMinor: entry.projectedRevenueMinor ?? entry.revenueMinor, expectedMarginMinor: entry.projectedMarginMinor ?? entry.marginMinor }));
  const scopedClientIds = new Set(p.data.clients.filter((row: Row) => ids.has(s(row, "ownerMemberId"))).map((row: Row) => s(row, "id")));
  const scopedInvoices = p.data.invoices.filter((row: Row) => scopedClientIds.has(s(row, "clientId")));
  const mtd = p.data.payments.filter((row: Row) => s(row, "receivedOn").startsWith(month) && scopedInvoices.some((invoice: Row) => s(invoice, "id") === s(row, "invoiceId"))).reduce((sum: number, row: Row) => sum + n(row, "amountMinor"), 0);
  const target = scoped.reduce((sum: number, row: Row) => sum + (reports[s(row, "fullName")]?.target || 0), 0);
  const total = confirmed.reduce((sum: number, row: Row) => sum + n(row, "expectedRevenueMinor"), 0); const margin = confirmed.reduce((sum: number, row: Row) => sum + n(row, "expectedMarginMinor"), 0);
  const remaining = confirmed.reduce((sum: number, row: Row) => { const linked = p.data.revenue.find((rev: Row) => s(rev, "id") === s(row, "revenueId")); return sum + Math.max(0, n(row, "expectedRevenueMinor") - (actual(linked) || 0)); }, 0);
  const projectedByEnd = target; const pipeTotal = backup.reduce((sum: number, row: Row) => sum + n(row, "expectedRevenueMinor") * Number(row.probability || 0) / 100, 0);
  const focusRows = confirmed.slice().sort((a: Row, b: Row) => n(b, "expectedRevenueMinor") - n(a, "expectedRevenueMinor")); const pipelineVisible = showPipeline ? backup : backup.slice(0, 10); const focusVisible = showFocus ? focusRows : focusRows.slice(0, 8);
  const label = p.scope === "overall" ? "All teams" : s(chosen, "teamName"); const paymentRows = scopedInvoices.filter((row: Row) => s(row, "dueDate").startsWith(month) || !!s(row, "dueDate") && s(row, "dueDate") < `${month}-01` && n(row, "totalMinor") > p.paid(s(row, "id"))).slice().sort((a: Row, b: Row) => s(a, "dueDate").localeCompare(s(b, "dueDate")));
  return <section className="admin-update"><div className="admin-switch"><div><p className="kicker">ADMIN SALES UPDATE · {monthLabel(month)}</p><h2>{label}</h2><p>{p.scope === "overall" ? "Combined reporting across all four BD teams." : "Team performance for " + label + ". Sellers: " + scoped.map((row: Row) => displayName(row)).join(", ")}</p></div><div className="scope-tabs"><button className={p.scope === "overall" ? "on" : ""} onClick={() => p.setScope("overall")}>Overall</button><button className={p.scope === "team" ? "on" : ""} onClick={() => p.setScope("team")}>Team-wise</button>{p.scope === "team" && <select aria-label="Choose team" value={s(chosen, "id")} onChange={(e) => p.setSelectedMember(e.target.value)}>{teams.map((row: Row) => <option key={s(row, "id")} value={s(row, "id")}>{s(row, "teamName")}</option>)}</select>}<label className="dashboard-month">Revenue month<input type="month" value={month} onChange={(e) => p.setFilter("dashboardMonth", e.target.value)}/></label></div></div>
    <MonthCarryForward month={month} save={p.save}/>
    <div className="update-head"><div className="update-brand"><b>{p.scope === "overall" ? "All BD Teams" : label}</b><span>SALES UPDATE — {monthLabel(month).toUpperCase()}</span><em>Focus. Execute. Achieve.</em></div><Stat icon="◎" label="Target / projected" value={m.format(target)}/><Stat icon="◒" label="MTD actual" value={m.format(mtd)} tone="mint"/><Stat icon="◔" label="Balance · target − MTD" value={m.format(target - mtd)} tone="sand"/><Stat icon="✓" label="Confirmed business" value={m.format(total)} tone="blue"/><div className="days-left"><b>{Math.max(0, new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0).getDate() - new Date().getDate())}</b><span>DAYS LEFT</span></div></div>
    <div className="update-progress"><div><span style={{ width: (target ? Math.min(100, Math.round(mtd / target * 100)) : 0) + "%" }}>{target ? Math.round(mtd / target * 100) : 0}%</span></div><small>{m.format(mtd)} <b>{m.format(target)}</b></small></div>
    <div className="update-grid"><UpdatePanel tone="green" title="CONFIRMED ACCOUNTS (L3 TO L5)"><MiniHeader cols={["Party", "Value", "Margin"]}/>{focusVisible.map((row: Row) => <MiniRow key={s(row, "id")} cols={[p.client(s(row, "clientId")), n(row, "expectedRevenueMinor") ? m.format(n(row, "expectedRevenueMinor")) : "Value TBD", n(row, "expectedRevenueMinor") ? Math.round(n(row, "expectedMarginMinor") / n(row, "expectedRevenueMinor") * 100) + "%" : "—"]}/>)}{focusRows.length > 8 && <button className="view-more" onClick={() => setShowFocus((value) => !value)}>{showFocus ? "Show less ↑" : "View more ↓"}</button>}<div className="mini-total"><b>Total</b><strong>{m.format(total)}</strong><strong>{m.format(margin)}</strong></div></UpdatePanel><UpdatePanel tone="navy" title="BACKUP / PIPELINE"><MiniHeader cols={["Party", "Value", "Stage"]}/>{pipelineVisible.map((row: Row) => <MiniRow key={s(row, "id")} cols={[p.client(s(row, "clientId")), n(row, "expectedRevenueMinor") ? m.format(n(row, "expectedRevenueMinor")) : "Value TBD", stageLabels[s(row, "stage")] || s(row, "stage")]}/>)}{backup.length > 10 && <button className="view-more" onClick={() => setShowPipeline((value) => !value)}>{showPipeline ? "Show less ↑" : "View more ↓"}</button>}<div className="mini-total"><b>Total</b><strong>{m.format(pipeTotal)}</strong><span>weighted opportunity</span></div></UpdatePanel></div>
    <div className="update-bottom"><UpdatePanel tone="red" title={"Payment details · " + monthLabel(month)}><div className="payment-list"><MiniHeader cols={["Client", "Balance", "Due date", "Status"]}/>{paymentRows.slice(0, 10).map((row: Row) => { const paid = p.paid(s(row, "id")), balance = Math.max(0, n(row, "totalMinor") - paid), overdue = balance > 0 && s(row, "dueDate") < today(), carried = balance > 0 && s(row, "dueDate") < `${month}-01`; return <MiniRow key={s(row, "id")} cols={[p.client(s(row, "clientId")), m.format(balance), fmtDate(s(row, "dueDate")), <span><Tag tone={balance <= 0 ? "mint" : overdue ? "red" : "amber"}>{balance <= 0 ? "Paid" : paid > 0 ? "Part paid" : overdue ? "Overdue" : "Unpaid"}</Tag>{carried && <small className="carry-forward-label">Carry-forward</small>}</span>]}/>; })}{!paymentRows.length && <Empty>No payments due in this month or carried from earlier months.</Empty>}</div></UpdatePanel></div>{p.scope === "overall" && ["admin", "manager"].includes(s(p.currentMember, "role")) && <OverallSummary data={p.data} month={month} paid={p.paid}/>}</section>;
}

function OverallSummary({ data, month }: { data: Data; month: string; paid: (id: string) => number }) {
  const heads = data.members.filter(row => s(row, "role") === "head" && row.isActive !== false);
  const rows = heads.map(head => { const team = s(head, "teamName"), members = data.members.filter(row => s(row, "teamName") === team && row.isActive !== false), ids = new Set(members.map(row => s(row, "id"))), clients = new Set(data.clients.filter(row => ids.has(s(row, "ownerMemberId"))).map(row => s(row, "id"))), invoices = new Set(data.invoices.filter(row => clients.has(s(row, "clientId"))).map(row => s(row, "id"))); const target = members.reduce((sum, row) => sum + (reports[s(row, "fullName")]?.target || 0), 0), actual = data.payments.filter(row => invoices.has(s(row, "invoiceId")) && s(row, "receivedOn").startsWith(month)).reduce((sum, row) => sum + n(row, "amountMinor"), 0), confirmed = data.revenue.filter(row => ids.has(s(row, "ownerMemberId")) && revenueMonth(row) === month).reduce((sum, row) => sum + projected(row), 0); return { head, team, target, actual, confirmed, balance: target - actual }; });
  const totals = rows.reduce((sum, row) => ({ target: sum.target + row.target, actual: sum.actual + row.actual, confirmed: sum.confirmed + row.confirmed, balance: sum.balance + row.balance }), { target: 0, actual: 0, confirmed: 0, balance: 0 });
  return <section className="data-panel management-summary"><div className="panel-title"><p className="kicker">OVERALL TEAM BREAKDOWN</p><h2>Team performance</h2><p className="form-hint">{monthLabel(month)} · projected equals target · balance = target − MTD actual</p></div><div className="performance-table-wrap"><table><thead><tr>{["Sr", "Team", "Head", "Target / projected", "MTD actual", "Confirmed business", "MTD / target", "Balance"].map(label => <th key={label}>{label}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={s(row.head, "id")}><td>{index + 1}</td><td>{row.team}</td><td>{displayName(row.head)}</td><td>{m.format(row.target)}</td><td>{m.format(row.actual)}</td><td>{m.format(row.confirmed)}</td><td>{row.target ? `${(row.actual / row.target * 100).toFixed(1)}%` : "—"}<div className="attainment-track"><i style={{ width: `${row.target ? Math.min(100, Math.max(0, row.actual / row.target * 100)) : 0}%` }}/></div></td><td>{m.format(row.balance)}</td></tr>)}</tbody><tfoot><tr><td>{rows.length}</td><td>Total</td><td/><td>{m.format(totals.target)}</td><td>{m.format(totals.actual)}</td><td>{m.format(totals.confirmed)}</td><td>{totals.target ? `${(totals.actual / totals.target * 100).toFixed(1)}%` : "—"}</td><td>{m.format(totals.balance)}</td></tr></tfoot></table></div></section>;
}

function Panel({ title, eyebrow, children, className = "" }: { title: string; eyebrow?: string; children: ReactNode; className?: string }) { return <section className={"data-panel " + className}><div className="panel-title">{eyebrow && <p className="kicker">{eyebrow}</p>}<h2>{title}</h2></div>{children}</section>; }
function Toolbar({ children }: { children: ReactNode }) { return <div className="table-toolbar">{children}</div>; }
function Select({ label, value, onChange, children }: { label: string; value: string; onChange: (v: string) => void; children: ReactNode }) { return <label className="filter-field"><span>{label}</span><select value={value} onChange={(e) => onChange(e.target.value)}>{children}</select></label>; }
function Tag({ children, tone = "mint" }: { children: ReactNode; tone?: string }) { return <span className={"status-tag " + tone}>{children}</span>; }
function TableHead({ cols, className = "" }: { cols: string[]; className?: string }) { const ref = useRef<HTMLDivElement>(null); useEffect(() => { ref.current?.parentElement?.querySelectorAll(".table-row").forEach(row => { [...row.children].forEach((cell, index) => cell.setAttribute("data-label", cols[index] || "")); }); }); return <div ref={ref} className={"table-head " + className}>{cols.map((col) => <b key={col}>{col}</b>)}</div>; }
function Empty({ children = "No records match these filters." }: { children?: ReactNode }) { return <div className="empty-state">{children}</div>; }
function Stat({ icon, label, value, tone = "blue" }: { icon: string; label: string; value: string; tone?: string }) { return <article className={"stat-card " + tone}><span>{icon}</span><div><small>{label}</small><strong>{value}</strong></div></article>; }
function UpdatePanel({ tone, title, children }: { tone: string; title: string; children: ReactNode }) { return <section className={"update-panel " + tone}><h3>{title}</h3><div className="update-panel-body">{children}</div></section>; }
function MiniHeader({ cols }: { cols: string[] }) { return <div className="mini-head">{cols.map((col) => <b key={col}>{col}</b>)}</div>; }
function MiniRow({ cols }: { cols: ReactNode[] }) { return <div className="mini-row">{cols.map((col, i) => <span key={i}>{col}</span>)}</div>; }

function Clients(p: any) {
  const month = p.filters.clientMonth || p.filters.dashboardMonth || today().slice(0, 7);
  const monthRevenue = p.data.revenue.filter((entry: Row) => revenueMonth(entry) === month);
  const rows = p.data.clients.filter((row: Row) => (!p.filters.clientSearch || s(row, "legalName").toLowerCase().includes(p.filters.clientSearch.toLowerCase())) && (p.filters.clientStaff === "all" || s(row, "ownerMemberId") === p.filters.clientStaff) && (p.filters.clientStatus === "all" || s(row, "status") === p.filters.clientStatus));
  return <Panel title="Client list" eyebrow="LINKED CUSTOMER RECORDS"><Toolbar><input placeholder="Search clients" value={p.filters.clientSearch} onChange={(e) => p.setFilter("clientSearch", e.target.value)}/><label className="filter-field"><span>Revenue month</span><input aria-label="Client revenue month" type="month" value={month} onChange={event => p.setFilter("clientMonth", event.target.value)}/></label><Select label="Staff" value={p.filters.clientStaff} onChange={(v) => p.setFilter("clientStaff", v)}><option value="all">All staff</option>{p.data.members.filter((r: Row) => s(r, "role") !== "admin").map((r: Row) => <option key={s(r, "id")} value={s(r, "id")}>{displayName(r)}</option>)}</Select><Select label="Status" value={p.filters.clientStatus} onChange={(v) => p.setFilter("clientStatus", v)}><option value="all">All statuses</option>{["l1", "l2", "l3", "l4", "l5", "on_hold", "lost", "prospect", "active"].map((v) => <option key={v} value={v}>{stageLabels[v] || (v === "on_hold" ? "On hold" : v.replaceAll("_", " "))}</option>)}</Select></Toolbar><p className="form-hint">Projected and actual revenue for {monthLabel(month)}. Amount due includes outstanding invoices from every month.</p><div className="data-table client-table"><TableHead cols={["Client name", "Staff (owner)", "Projected revenue", "Actual revenue", "Amount due", "Payment terms", "Status", "Last edited", "Actions"]}/>{rows.length ? rows.map((row: Row) => {
    const id = s(row, "id"), owner = p.owner(s(row, "ownerMemberId")), entries = monthRevenue.filter((entry: Row) => s(entry, "clientId") === id);
    const projectedValue = entries.reduce((sum: number, entry: Row) => sum + projected(entry), 0), actualValue = entries.reduce((sum: number, entry: Row) => sum + (actual(entry) || 0), 0);
    const invoices = p.data.invoices.filter((invoice: Row) => s(invoice, "clientId") === id), due = invoices.reduce((sum: number, invoice: Row) => sum + Math.max(0, n(invoice, "totalMinor") - p.paid(s(invoice, "id"))), 0);
    const edited = "by " + (owner || "staff") + " on " + fmtDate(s(row, "updatedAt") || s(row, "createdAt"));
    return <div className="table-row" key={id}><strong>{p.client(id)}</strong><span>{owner}</span><span>{m.format(projectedValue)}</span><span>{m.format(actualValue)}</span><span>{!invoices.length && projectedValue > 0 ? "Not invoiced" : m.format(due)}</span><span>Net {s(row, "paymentTermsDays") || "30"}</span><span><Tag tone={s(row, "status") === "active" ? "mint" : "blue"}>{stageLabels[s(row, "status")] || s(row, "status") || "prospect"}</Tag></span><small>{edited}</small><button className="mini-link" title={edited} onClick={() => p.setEditingClient(row)}>Edit / View</button></div>;
  }) : <Empty/>}</div></Panel>;
}


function Revenue(p: any) {
  const now = new Date();
  const currentMonth = now.toISOString().slice(0, 7);
  const previousMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1).toISOString().slice(0, 7);
  const range = p.filters.revenueRange;
  const rows = p.data.revenue.filter((row: Row) => {
    if (p.filters.revenueStaff !== "all" && s(row, "ownerMemberId") !== p.filters.revenueStaff) return false;
    const month = revenueMonth(row);
    if (range === "this") return month === currentMonth;
    if (range === "last") return month === previousMonth;
    return (!p.filters.revenueFrom || s(row, "entryDate") >= p.filters.revenueFrom) && (!p.filters.revenueTo || s(row, "entryDate") <= p.filters.revenueTo);
  });
  const projectedRevenue = rows.reduce((sum: number, row: Row) => sum + projected(row), 0);
  const actualRevenue = rows.reduce((sum: number, row: Row) => sum + (actual(row) || 0), 0);
  const projectedMarginValue = rows.reduce((sum: number, row: Row) => sum + projectedMargin(row), 0);
  const actualMarginValue = rows.reduce((sum: number, row: Row) => sum + (actualMargin(row) || 0), 0);
  return <Panel title="Revenue and margin" eyebrow="DATE-WISE PERFORMANCE"><Toolbar><Select label="Staff" value={p.filters.revenueStaff} onChange={(v) => p.setFilter("revenueStaff", v)}><option value="all">All staff</option>{p.data.members.filter((r: Row) => s(r, "role") !== "admin").map((r: Row) => <option key={s(r, "id")} value={s(r, "id")}>{displayName(r)}</option>)}</Select><Select label="Date range" value={range} onChange={(v) => p.setFilter("revenueRange", v)}><option value="this">This month</option><option value="last">Last month</option><option value="custom">Custom</option></Select>{range === "custom" && <><input type="date" value={p.filters.revenueFrom} onChange={(e) => p.setFilter("revenueFrom", e.target.value)}/><input type="date" value={p.filters.revenueTo} onChange={(e) => p.setFilter("revenueTo", e.target.value)}/></>}</Toolbar><div className="summary-cards"><Stat icon="↗" label="Projected revenue" value={m.format(projectedRevenue)} tone="mint"/><Stat icon="✓" label="Actual revenue" value={m.format(actualRevenue)} tone="sand"/><Stat icon="%" label="Projected margin" value={m.format(projectedMarginValue)} tone="violet"/><Stat icon="%" label="Actual margin" value={m.format(actualMarginValue)} tone="blue"/></div><div className="data-table revenue-table"><TableHead cols={["Client", "Staff", "Revenue month", "Projected revenue", "Margin %", "Projected margin", "Actual revenue", "Actual margin", "Status", "Updated actual", "Actions"]}/>{rows.length ? rows.map((row: Row) => { const projectedValue = projected(row), projectedMarginValue = projectedMargin(row), actualValue = actual(row), actualMarginValue = actualMargin(row), updatedBy = p.owner(s(row, "actualUpdatedByMemberId")); return <div className="table-row" key={s(row, "id")}><strong>{p.client(s(row, "clientId"))}</strong><span>{p.owner(s(row, "ownerMemberId"))}</span><span>{monthLabel(revenueMonth(row))}</span><span>{m.format(projectedValue)}</span><span>{projectedValue ? Math.round(projectedMarginValue / projectedValue * 100) : 0}%</span><span>{m.format(projectedMarginValue)}</span><span>{actualValue === null ? "-" : m.format(actualValue)}</span><span>{actualMarginValue === null ? "-" : m.format(actualMarginValue)}</span><span><Tag tone={revenueStatus(row) === "Received" ? "mint" : revenueStatus(row) === "Partly received" ? "amber" : "blue"}>{revenueStatus(row)}</Tag></span><small>{s(row, "actualUpdatedAt") ? "by " + updatedBy + " on " + fmtDate(s(row, "actualUpdatedAt")) : "—"}</small><button className="mini-link" onClick={() => p.setRevenueActual(row)}>Update actual</button></div>; }) : <Empty/>}</div></Panel>;
}


function Calls(p: any) { return <Panel title="Cold calls" eyebrow="ACTIVITY LOG"><div className="data-table calls-table"><TableHead cols={["Client / prospect", "Staff", "Called at", "Outcome", "Next follow-up", "Notes"]}/>{p.data.calls.length ? p.data.calls.map((row: Row) => <div className="table-row" key={s(row, "id")}><strong>{s(row, "clientId") ? p.client(s(row, "clientId")) : s(row, "prospectName")}</strong><span>{p.owner(s(row, "callerMemberId"))}</span><span>{fmtDate(s(row, "calledAt"))}</span><span><Tag tone="blue">{s(row, "outcome").replaceAll("_", " ")}</Tag></span><span>{fmtDate(s(row, "nextFollowUpAt"))}</span><span>{s(row, "notes") || "—"}</span></div>) : <Empty>No calls have been logged yet.</Empty>}</div></Panel>; }

function Calendar(p: any) { const d = p.calendarDate as Date, year = d.getFullYear(), month = d.getMonth(), first = new Date(year, month, 1), start = new Date(year, month, 1 - first.getDay()), cells = Array.from({ length: 42 }, (_, i) => new Date(start.getFullYear(), start.getMonth(), start.getDate() + i)), events = p.data.meetings; const shift = (delta: number) => p.setCalendarDate(new Date(year, month + delta, d.getDate())); const dayEvents = (date: Date) => events.filter((e: Row) => s(e, "scheduledAt").slice(0, 10) === date.toISOString().slice(0, 10)); return <Panel title="Calendar" eyebrow="MEETINGS AND FOLLOW-UPS"><div className="calendar-toolbar"><button className="ghost" onClick={() => p.setCalendarDate(new Date())}>Today</button><button className="icon-button" onClick={() => shift(-1)}>‹</button><button className="icon-button" onClick={() => shift(1)}>›</button><b>{d.toLocaleDateString("en-IN", { month: "long", year: "numeric" })}</b><div className="segmented">{["month", "week", "day"].map((mode) => <button key={mode} className={p.calendarMode === mode ? "on" : ""} onClick={() => p.setCalendarMode(mode)}>{mode[0].toUpperCase() + mode.slice(1)}</button>)}</div></div>{p.calendarMode === "month" ? <div className="calendar-grid"><div className="calendar-weekdays">{["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => <b key={day}>{day}</b>)}</div><div className="month-cells">{cells.map((date) => <button className={date.getMonth() === month ? "calendar-cell" : "calendar-cell muted"} key={date.toISOString()} onClick={() => p.openMeeting(date.toISOString().slice(0, 10))}><time>{date.getDate()}</time>{dayEvents(date).slice(0, 2).map((event: Row) => <span className="calendar-event" key={s(event, "id")}>{s(event, "title")}</span>)}</button>)}</div></div> : <div className="calendar-slots">{Array.from({ length: 12 }, (_, i) => 8 + i).map((hour) => <div className="time-slot" key={hour}><time>{String(hour).padStart(2, "0")}:00</time><div>{events.filter((event: Row) => { const date = s(event, "scheduledAt"); return date.slice(0, 10) === d.toISOString().slice(0, 10) && new Date(date).getHours() === hour; }).map((event: Row) => <article className="calendar-event large" key={s(event, "id")}><b>{s(event, "title")}</b><span>{s(event, "attendeeName")}</span></article>)}</div></div>)}</div>}</Panel>; }

function Invoices(p: any) { const list = p.data.invoices.filter((row: Row) => { const balance = Math.max(0, n(row, "totalMinor") - p.paid(s(row, "id"))), days = Math.ceil((new Date(s(row, "dueDate") + "T00:00:00").getTime() - new Date(today() + "T00:00:00").getTime()) / 86400000); return p.filters.invoiceFilter === "all" || (p.filters.invoiceFilter === "overdue" && balance > 0 && days < 0) || (p.filters.invoiceFilter === "due_soon" && balance > 0 && days >= 0 && days <= 3); }); const overdue = p.overdue.length; return <Panel title="Invoices and payments" eyebrow="COLLECTION CONTROL"><div className="invoice-summary"><Stat icon="!" label="Overdue invoices" value={String(overdue)} tone="red"/><Select label="Filter" value={p.filters.invoiceFilter} onChange={(v) => p.setFilter("invoiceFilter", v)}><option value="all">All invoices</option><option value="overdue">Overdue</option><option value="due_soon">Due soon</option></Select></div><div className="data-table invoice-table"><TableHead cols={["Invoice no.", "Client", "Staff", "Invoice date", "Due date", "Amount", "Paid", "Balance", "Status", "Actions"]}/>{list.length ? list.map((row: Row) => { const balance = Math.max(0, n(row, "totalMinor") - p.paid(s(row, "id"))), days = Math.ceil((new Date(s(row, "dueDate") + "T00:00:00").getTime() - new Date(today() + "T00:00:00").getTime()) / 86400000), isOverdue = balance > 0 && days < 0, soon = balance > 0 && days >= 0 && days <= 3; const status = balance <= 0 ? "Paid" : p.paid(s(row, "id")) > 0 ? "Part paid" : isOverdue ? "Overdue" : soon ? "Due soon" : "Sent"; return <div className={"table-row " + (isOverdue ? "overdue-row" : "")} key={s(row, "id")}><strong>{s(row, "invoiceNumber")}</strong><span>{p.client(s(row, "clientId"))}</span><span>{p.owner(s(row, "createdByMemberId"))}</span><span>{fmtDate(s(row, "issueDate"))}</span><span>{fmtDate(s(row, "dueDate"))}</span><span>{m.format(n(row, "totalMinor"))}</span><span>{m.format(p.paid(s(row, "id")))}</span><span>{m.format(balance)}</span><span><Tag tone={isOverdue ? "red" : soon ? "amber" : status === "Paid" ? "mint" : "blue"}>{isOverdue ? `Overdue (${Math.abs(days)} days)` : status}</Tag></span><button className="mini-link" onClick={() => p.setPaymentOpen(row)}>Record payment</button></div>; }) : <Empty/>}</div></Panel>; }

function Vendors(p: any) { const rows = p.data.vendors.filter((row: Row) => s(row, "vendorName").toLowerCase() !== "durgesh" && (!p.filters.vendorSearch || s(row, "vendorName").toLowerCase().includes(p.filters.vendorSearch.toLowerCase()) || p.client(s(row, "clientId")).toLowerCase().includes(p.filters.vendorSearch.toLowerCase())) && (p.filters.vendorStaff === "all" || s(row, "ownerMemberId") === p.filters.vendorStaff)); const total = rows.reduce((sum: number, row: Row) => sum + n(row, "amountMinor"), 0); return <Panel title="Vendors" eyebrow="PARTNER PAYABLES"><Toolbar><input placeholder="Search vendors or clients" value={p.filters.vendorSearch} onChange={(e) => p.setFilter("vendorSearch", e.target.value)}/><Select label="Staff" value={p.filters.vendorStaff} onChange={(v) => p.setFilter("vendorStaff", v)}><option value="all">All staff</option>{p.data.members.filter((r: Row) => s(r, "role") !== "admin").map((r: Row) => <option key={s(r, "id")} value={s(r, "id")}>{displayName(r)}</option>)}</Select></Toolbar><div className="data-table vendor-table"><TableHead cols={["Vendor name", "Client", "Amount payable", "Client payment received", "Due date", "Vendor status", "Staff"]}/>{rows.map((row: Row) => <div className="table-row" key={s(row, "id")}><strong>{s(row, "vendorName")}</strong><span>{p.client(s(row, "clientId"))}</span><span>{m.format(n(row, "amountMinor"))}</span><span><Tag tone={s(row, "clientPayment") === "yes" ? "mint" : "amber"}>{s(row, "clientPayment") === "yes" ? "Yes" : "No"}</Tag></span><span>{fmtDate(s(row, "dueDate"))}</span><span>{s(row, "status") || "Open"}</span><span>{p.owner(s(row, "ownerMemberId"))}</span></div>)}<div className="table-total"><b>Total payable</b><strong>{m.format(total)}</strong></div></div></Panel>; }

function Agreements(p: any) { const unique: Row[] = p.data.agreements; return <Panel title="Agreements" eyebrow="CONTRACT CONTROL"><div className="data-table agreement-table"><TableHead cols={["Agreement", "Client", "Value", "Start date", "Expiry date", "Status", "Actions"]}/>{unique.map((row: Row) => { const days = Math.ceil((new Date(s(row, "expiryDate") + "T00:00:00").getTime() - new Date(today() + "T00:00:00").getTime()) / 86400000), soon = days >= 0 && days <= 60; return <div className={"table-row " + (soon ? "expiring-row" : "")} key={s(row, "id")}><strong>{s(row, "title")}</strong><span>{p.client(s(row, "clientId"))}</span><span>{m.format(n(row, "valueMinor"))}</span><span>{fmtDate(s(row, "effectiveDate"))}</span><span>{fmtDate(s(row, "expiryDate"))}{soon && <small className="expiry-note">Expiring within 60 days</small>}</span><span><Tag>{s(row, "status")}</Tag></span><button className="mini-link" onClick={() => p.setAgreementOpen(row)}>View</button></div>; })}</div></Panel>; }

function Team(p: any) { const staff: Row[] = p.data.members.filter((row: Row) => s(row, "role") !== "admin" && s(row, "isActive") !== "false"), groups = [...new Set<string>(staff.map((row: Row) => s(row, "teamName")))]; return <Panel title="Teams and access" eyebrow="PEOPLE DIRECTORY"><div className="expanded-teams">{groups.map((team) => { const members = staff.filter((row: Row) => s(row, "teamName") === team), head = members.find((row: Row) => s(row, "role") === "head") || members[0], canManage = s(p.currentMember, "role") === "admin" || s(p.currentMember, "id") === s(head, "id"); return <article className="team-card" key={team}><div><p className="kicker">TEAM</p><h3>{team}</h3><p>{members.length === 1 ? "1 active member" : members.length + " active members"} · Head: {displayName(head)}</p></div><button className="ghost" onClick={() => p.setTeamOpen(team)} disabled={!canManage}>+ Add member</button><div className="team-member-list">{members.map((member: Row) => <div key={s(member, "id")}><span><b>{displayName(member)}</b><small>{s(member, "role") === "head" ? "Team head" : "BD member"} · {displayEmail(member)}</small></span>{canManage && s(member, "id") !== s(head, "id") && <button className="danger-link" onClick={() => void p.removeMember(s(member, "id"))}>Remove</button>}{s(member, "role") !== "head" && s(p.currentMember, "role") === "admin" && <button className="mini-link" onClick={() => void p.resetPassword(s(member, "id"))}>Reset password</button>}</div>)}</div></article>; })}</div></Panel>; }



function RevenueActualDialog({ revenue, client, onClose, onSave }: { revenue: Row; client: (id: string) => string; onClose: () => void; onSave: (e: FormEvent<HTMLFormElement>) => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">REVENUE UPDATE</p><h2>Update actual revenue</h2><p>{client(s(revenue, "clientId"))} · projected {m.format(projected(revenue))} · margin {Math.round(projectedMargin(revenue) / Math.max(1, projected(revenue)) * 100)}%</p></div><form className="crm-form" onSubmit={onSave}><label>Actual revenue<input name="actualRevenue" type="number" min="0" defaultValue={actual(revenue) === null ? "" : actual(revenue) || ""} required/></label><p className="form-hint">Actual margin is calculated from the projected margin percentage. Saving replaces the previous actual value.</p><div className="form-actions"><button className="ghost" type="button" onClick={onClose}>Cancel</button><button className="primary">Save actual</button></div></form></section></div>; }

function CallImportDialog({ preview, onFile, onClose, onSave }: { preview: { row: Record<string, string>; error: string }[]; onFile: (file: File) => void; onClose: () => void; onSave: () => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal wide-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">BULK IMPORT</p><h2>Upload calls</h2><p>Upload a CSV or Excel export. Preview and fix row-level errors before saving.</p></div><label className="upload-drop">Choose Excel / CSV<input type="file" accept=".csv,.xlsx,.xls" onChange={(e) => e.target.files?.[0] && onFile(e.target.files[0])}/></label>{preview.length > 0 && <div className="import-preview"><TableHead cols={["Client / prospect", "Called at", "Outcome", "Validation"]}/>{preview.map((item, i) => <div className={"table-row " + (item.error ? "error-row" : "")} key={i}><span>{item.row.client || item.row.prospectName || item.row.clientId || "—"}</span><span>{item.row.calledAt || "—"}</span><span>{item.row.outcome || "—"}</span><span>{item.error || "Ready"}</span></div>)}</div>}<div className="form-actions"><button className="ghost" onClick={onClose}>Cancel</button><button className="primary" onClick={onSave} disabled={!preview.length}>Save valid rows</button></div></section></div>; }

function TeamMemberDialog({ team, onClose, onSave }: { team: string; onClose: () => void; onSave: (body: Record<string, string>) => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">TEAM MEMBERS</p><h2>Add member to {team}</h2></div><form className="crm-form" onSubmit={(e) => { e.preventDefault(); onSave(Object.fromEntries(new FormData(e.currentTarget).entries()) as Record<string, string>); }}><label>Full name<input name="fullName" required/></label><label>Real email<input name="email" type="email" required/></label><label>Role<select name="role"><option value="staff">BD member</option><option value="head">Team head</option></select></label><div className="form-actions"><button className="ghost" type="button" onClick={onClose}>Cancel</button><button className="primary">Add member</button></div></form></section></div>; }


function PaymentDialog({ invoice, onClose, onSave }: { invoice: Row; onClose: () => void; onSave: (e: FormEvent<HTMLFormElement>) => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">INVOICE PAYMENT</p><h2>Record payment</h2><p>{s(invoice, "invoiceNumber")} · balance to collect</p></div><form className="crm-form" onSubmit={onSave}><label>Amount received<input name="amount" type="number" min="1" required/></label><label>Payment date<input name="receivedOn" type="date" defaultValue={today()} required/></label><label>Mode<select name="method"><option value="bank_transfer">Bank transfer</option><option value="upi">UPI</option><option value="cash">Cash</option><option value="cheque">Cheque</option></select></label><label>Reference<input name="referenceNo" placeholder="UTR / receipt no."/></label><div className="form-actions"><button type="button" className="ghost" onClick={onClose}>Cancel</button><button className="primary">Save payment</button></div></form></section></div>; }
function PipelineInvoiceDialog({ deal, onClose, onSave }: { deal: Row; onClose: () => void; onSave: (e: FormEvent<HTMLFormElement>) => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">L5 BILLING</p><h2>Create invoice</h2><p>Choose the invoice date for {s(deal, "title")}.</p></div><form className="crm-form" onSubmit={onSave}><label>Invoice date<input name="invoiceDate" type="date" defaultValue={today()} required/></label><div className="form-actions"><button type="button" className="ghost" onClick={onClose}>Cancel</button><button className="primary">Move to L5</button></div></form></section></div>; }
function PipelineSettingsDialog({ settings, onClose, onSave }: { settings?: Row; onClose: () => void; onSave: (values: Record<string, string>) => void }) { let values: Record<string, number> = { l1: 20, l2: 50, l3: 100, l4: 100, l5: 100 }; try { values = { ...values, ...JSON.parse(s(settings, "probabilities")) }; } catch {} return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">ADMIN SETTINGS</p><h2>Stage probabilities</h2></div><form className="crm-form" onSubmit={(e) => { e.preventDefault(); onSave(Object.fromEntries(new FormData(e.currentTarget).entries()) as Record<string, string>); }}>{stages.map((stage) => <label key={stage}>{stageLabels[stage]}<input name={stage} type="number" min="0" max="100" defaultValue={String(values[stage])}/></label>)}<div className="form-actions"><button type="button" className="ghost" onClick={onClose}>Cancel</button><button className="primary">Save settings</button></div></form></section></div>; }
function AuthHelpDialog({ onClose }: { onClose: () => void }) { return <div className="record-modal-backdrop" onClick={onClose}><section className="entry record-modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="entry-intro"><p className="kicker">ACCOUNT ACCESS</p><h2>Forgot password?</h2><p>Ask your administrator to reset your CRM password. They can issue a temporary password and your next sign-in will require a change.</p></div><div className="form-actions"><button className="primary" onClick={onClose}>Close</button></div></section></div>; }
